import BalanceInformations from "./components/BalanceInformations";
import Header from "./components/Header";
import Main from "./components/Main";
import ActionsSection from "./components/Actions";
import BalanceActions from "./components/BalanceActions";
import LoansActions from "./components/LoansActions";
import AccountActions from "./components/AccountActions";

const initalState = {
  isAccountOpen: false,
};

function App() {
  return (
    <div className="app">
      <Header />
      <Main>
        <BalanceInformations />
        <ActionsSection>
          <BalanceActions />
          <LoansActions />
          <AccountActions />
        </ActionsSection>
      </Main>
    </div>
  );
}

export default App;
